// @ts-nocheck
export const code = async (inputs) => {
  let parsed = {"parent_response": "", "promise_date": ""};
  function cdmNum(s, integer) { const t = String(s).replace(/₹|\b(?:rs\.?|inr)(?![a-z])/gi, ' ').trim(); if (/0x[0-9a-f]/i.test(t) || /\d\s*e\s*[+-]?\d/i.test(t) || /\d\.\d{3},\d/.test(t) || /\d\.\d+\.\d/.test(t)) return null; const m = t.match(/-?\d[\d,]*(\.\d+)?/); if (!m) return null; let x = Number(m[0].replace(/,/g, '')); if (!isFinite(x)) return null; const u = t.slice(m.index + m[0].length).trim().toLowerCase().match(/^(thousand|k|lakhs?|lacs?|l|crores?|cr|million|mn)(?![a-z])/); if (u) x = x * (/^(thousand|k)$/.test(u[1]) ? 1e3 : /^(million|mn)$/.test(u[1]) ? 1e6 : /^(lakhs?|lacs?|l)$/.test(u[1]) ? 1e5 : 1e7); x = parseFloat(x.toPrecision(15)); return integer && !Number.isInteger(x) ? null : x; }
  function cdmBool(s) { const t = String(s).trim().toLowerCase().replace(/[.!?।]+$/, ''); if (['yes', 'y', 'true', '1', 'haan', 'हाँ', 'हां', 'હા'].includes(t)) return true; if (['no', 'n', 'false', '0', 'nahi', 'नहीं', 'ना', 'ના'].includes(t)) return false; return null; }
  function cdmChoice(s, ch) { const t = String(s).trim().toLowerCase(); const L = ch.map((c) => [c, String(c).toLowerCase()]); const exact = L.find((x) => x[1] === t); if (exact) return exact[0]; const esc = (x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); const inSpan = L.filter((x) => new RegExp('(^|[^a-z0-9])' + esc(x[1]) + '([^a-z0-9]|$)').test(t)).sort((a, b) => b[1].length - a[1].length); if (inSpan.length) return inSpan[0][0]; const inChoice = t.length >= 2 ? L.find((x) => x[1].includes(t)) : null; return inChoice ? inChoice[0] : null; }
  function cdmFields(fields, decl, conf, choices) { if (typeof fields === 'string') { try { fields = JSON.parse(fields); } catch (e) { fields = null; } } const ents = fields && Array.isArray(fields.entities) ? fields.entities : null; const keys = Object.keys(decl); const out = Object.create(null); for (const k of keys) out[k] = null; if (!ents) { out._parse_error = 'true'; if (conf) out[conf] = 0; out.fields_found = 0; out.fields_total = keys.length; return out; } const best = Object.create(null); for (const e of ents) { if (!e || !Object.prototype.hasOwnProperty.call(decl, e.type) || e.text === undefined || e.text === null || String(e.text).trim() === '') continue; const c = Number(e.confidence) || 0; if (!best[e.type] || c > best[e.type].c) best[e.type] = { v: String(e.text).trim(), c }; } const cs = []; for (const k of keys) { const b = best[k]; if (!b) continue; const t = decl[k]; const ch = choices && Array.isArray(choices[k]) && choices[k].length ? choices[k] : null; const v = (t === 'integer' || t === 'number') ? cdmNum(b.v, t === 'integer') : t === 'boolean' ? cdmBool(b.v) : ch ? cdmChoice(b.v, ch) : b.v; if (v === null) continue; out[k] = v; cs.push(b.c); } if (conf) out[conf] = cs.length ? Math.min(...cs) : 0; out.fields_found = cs.length; out.fields_total = keys.length; return out; }
  { const got = cdmFields(inputs.ai_fields, {"parent_response": "string", "promise_date": "string"}, null, {}); for (const [k, v] of Object.entries(got)) if (v !== null) parsed[k] = v; }   // Pucho CDM extract → one value per field
  const JEVP = {}; for (const k of Object.keys(inputs)) if (k.indexOf('jev_') === 0 && k.slice(-11) !== '_confidence') { const f = k.slice(4), v = inputs[k], conf = Number(inputs[k + '_confidence']); const pol = JEVP[f] || [0.5, null]; if (v !== undefined && v !== '' && (isNaN(conf) || conf >= pol[0])) parsed[f] = v; else if (pol[1] !== null && pol[1] !== undefined) parsed[f] = pol[1]; } /* a Jev answer lands only when confident; else the fallback */
  const build = async (inputs) => {
  const C = inputs.C, p = inputs.b || {}, r = parsed || {};
  const allowed = ["Fee_ID", "Created_At", "Student_ID", "Student_Name", "Parent_Name", "Parent_Phone", "Course", "Instalment", "Amount_INR", "Paid_INR", "Balance_INR", "Due_Date", "Days_Overdue", "Status", "Reminder_Count", "Last_Reminder_At", "Payment_Link", "Promise_Date", "Parent_Response", "Paid_At", "Payment_Mode", "Receipt_No"]; const fills = {"Last_Reminder_At": "now", "Parent_Response": "Simulated call — will pay by Friday"};
  const title = (s) => s.replace(/(^|_)(\w)/g, (m, a, b) => a + b.toUpperCase());
  const row = {}; for (const k of allowed) { if (p[k] !== undefined) row[k] = p[k]; else if (r[k] !== undefined) row[k] = r[k]; else if (r[k.toLowerCase()] !== undefined) row[k] = r[k.toLowerCase()]; }
  for (const k of Object.keys(r)) { const t = title(k); if (allowed.includes(t) && row[t] === undefined) row[t] = Array.isArray(r[k]) ? r[k].join('; ') : r[k]; }
  for (const [k, v] of Object.entries(fills)) row[k] = v === 'now' ? new Date().toISOString() : v;
  const id = p['Fee_ID']; const patch = {}; for (const k of allowed) if (k !== 'Fee_ID' && row[k] !== undefined && row[k] !== '') patch[k] = row[k];
  return { patch, id };
};
  const out = await build(inputs);
  return { ...out, result: parsed };
};

// @ts-nocheck
// lib: the app's src/lib/renderMessage.js, copied verbatim so the flow and the app word a message the same way
// src/lib/renderMessage.js — a client message from a fixed template (os.yaml `sends.message`), rule zero: the words
// are the firm's, the values are the record's, no model is involved. ONE source: the app imports it to show what a
// simulated send would have said, and build_flows.py embeds this same file in the flow's CODE node, so the wired flow
// and the simulation can never word a message differently. Plain JS, no imports — it must run inside Studio as is.
//   send = { to: <payload key>, lang: <payload key>, message: { en, hi, mr, … }, words: { hi: { Adjourned: '…' } }, template: { name, variables: { '1': '{{Col}}' } } }
//   {{Key}} → the payload value · {{constants.x}} → the flow constant · [[ … ]] → dropped when any value inside is empty
//   dates (YYYY-MM-DD or ISO) → "Thu, 2 Oct 2026" / "Thu, 2 Oct 2026, 4:30 pm" in IST · phone → digits with 91 prefix
function renderMessage(send, vars, constants) {
  const LANG = { english: 'en', en: 'en', hindi: 'hi', hi: 'hi', marathi: 'mr', mr: 'mr', gujarati: 'gu', gu: 'gu', tamil: 'ta', ta: 'ta', telugu: 'te', te: 'te', kannada: 'kn', kn: 'kn', bengali: 'bn', bn: 'bn', malayalam: 'ml', ml: 'ml', punjabi: 'pa', pa: 'pa' };
  const msg = (send && send.message) || {};
  const asked = LANG[String((vars || {})[send.lang] || '').trim().toLowerCase()] || 'en';
  const lang = msg[asked] ? asked : (msg.en ? 'en' : Object.keys(msg)[0]);
  const words = ((send.words || {})[lang]) || {};
  const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const date = (v) => {
    const only = /^\d{4}-\d{2}-\d{2}$/.test(v);
    const t = only ? Date.UTC(+v.slice(0, 4), +v.slice(5, 7) - 1, +v.slice(8, 10)) : Date.parse(v) + 330 * 60000;   // IST without Intl
    if (isNaN(t)) return v; const d = new Date(t);
    let s = `${DAYS[d.getUTCDay()]}, ${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
    if (!only) { const h = d.getUTCHours(), m = d.getUTCMinutes(); s += `, ${((h + 11) % 12) + 1}:${String(m).padStart(2, '0')} ${h < 12 ? 'am' : 'pm'}`; }
    return s;
  };
  const val = (k) => {
    let v = k.indexOf('constants.') === 0 ? (constants || {})[k.slice(10)] : (vars || {})[k];
    if (v === undefined || v === null) return '';
    v = String(v).trim();
    if (/^\d{4}-\d{2}-\d{2}([T ][\d:.]+(Z|[+-]\d{2}:?\d{2})?)?$/.test(v)) v = date(v);
    return words[v] !== undefined ? words[v] : v;
  };
  const fill = (s) => s.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, k) => val(k));
  let text = String(msg[lang] || '')
    .replace(/\[\[([\s\S]*?)\]\]/g, (_, part) => (part.match(/\{\{\s*([\w.]+)\s*\}\}/g) || []).every((p) => val(p.replace(/[{}\s]/g, '')) !== '') ? part : '');
  text = fill(text).replace(/[ \t]{2,}/g, ' ').replace(/ +([.,।])/g, '$1').trim();
  const digits = String((vars || {})[send.to] || '').replace(/\D/g, '');
  const to = digits.length === 10 ? '91' + digits : digits;
  // v4.4 — an approved WhatsApp template (os.yaml `sends.template`): the words live on whatsapp.pucho.ai, the flow fills only the
  // variables, each a {{Column}} template rendered the same way as a message. `to_e164` is the `+91…` form pucho-whatsapp takes.
  const tpl = send && send.template; const variables = {};
  if (tpl && tpl.variables) for (const k of Object.keys(tpl.variables)) variables[k] = fill(String(tpl.variables[k])).trim();
  return { to, to_e164: to ? '+' + to : '', lang, text, template: tpl ? (tpl.name || '') : '', variables };
}

// end lib
const SEND = {"tool": "whatsapp", "to": "Parent_Phone", "template": {"name": "eduflow_fee_payment_link", "variables": {"1": "{{Parent_Name}}", "2": "{{Student_Name}}", "3": "{{Balance_INR}}", "4": "{{Due_Date}}", "5": "{{Payment_Link}}"}}};
export const code = async (inputs) => renderMessage(SEND, { ...(inputs.b || {}) }, inputs.C || {});

